import{_ as e,o as t,c as i,ag as s}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"串联 SQL、计算与报警","description":"以演示温度串起查询数据点、计算输出、阈值报警、页面权限和运行验证，逐步找到各模块成果。","frontmatter":{"title":"串联 SQL、计算与报警","description":"以演示温度串起查询数据点、计算输出、阈值报警、页面权限和运行验证，逐步找到各模块成果。","status":"reviewed","kind":"tutorial"},"headers":[],"relativePath":"zh/guide/data-flow-tutorial.md","filePath":"zh/使用指南/串联SQL计算与报警.md"}'),r={name:"zh/guide/data-flow-tutorial.md"};function o(n,a,p,h,d,l){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="串联-sql、计算与报警" tabindex="-1">串联 SQL、计算与报警 <a class="header-anchor" href="#串联-sql、计算与报警" aria-label="Permalink to &quot;串联 SQL、计算与报警&quot;">​</a></h1><p>本教程用演示温度说明模块怎样配合：<strong>SQL 查询 → 数值数据点 → 计算输出 → 报警 → 页面与运行核对</strong>。只在练习工程操作，不改变真实设备和正式业务。</p><p>示例的 25、77、80 都是教学数值，不是现场采样，也不是平台已经执行过的测试结果。</p><h2 id="_1-生成一个数值温度点" tabindex="-1">1. 生成一个数值温度点 <a class="header-anchor" href="#_1-生成一个数值温度点" aria-label="Permalink to &quot;1. 生成一个数值温度点&quot;">​</a></h2><p>按<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点指南</a>，在获准的练习连接运行：</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 25</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> temperature;</span></span></code></pre></div><p>从“输出配置”选择“提取单个字段”，提取 <code>temperature</code>，保存并生成数据点。复制实际路径，到数据点列表核对它是数值，而不是完整结果集对象。</p><p><strong>这一阶段的结果</strong>：知道查询在哪个接入源、点在哪里，且能从点返回查询来源。</p><h2 id="_2-把温度点作为计算输入" tabindex="-1">2. 把温度点作为计算输入 <a class="header-anchor" href="#_2-把温度点作为计算输入" aria-label="Permalink to &quot;2. 把温度点作为计算输入&quot;">​</a></h2><p>到 **“计算单元”**新建或打开一个练习单元，在“变量”绑定刚才的真实数据点。</p><p>从当前语言的代码模板读取绑定点，再实现摄氏转华氏的逻辑：<strong>摄氏温度 × 1.8 + 32</strong>。可让 AI 根据当前单元语言与模板辅助完成，但要求它使用已确认的输入点，不编造路径。</p><p>配置一个数值输出，单位填写清楚，保存后试运行。输入为 25 时，预期换算结果为 77；失败时检查输入类型、变量和脚本，不把空值转换为正常零值。</p><p><strong>这一阶段的结果</strong>：保存后的单元能在试运行中返回预期结果；这还没有写入输出点，也没有证明正式触发正在执行。</p><h2 id="_3-找到计算输出-再配置报警" tabindex="-1">3. 找到计算输出，再配置报警 <a class="header-anchor" href="#_3-找到计算输出-再配置报警" aria-label="Permalink to &quot;3. 找到计算输出，再配置报警&quot;">​</a></h2><p>复制计算单元保存后的实际输出路径，到 **“数据点”**查找，使用来源入口回到相同计算单元。</p><p>按<a href="/induframe-docs/zh/guide/point-alarms.html">报警指南</a>，为这个华氏温度输出配置一个“高于 80”的练习报警，使用正确单位，先不向真实收件人发送通知。</p><p>在“开发调试”用样本试算：77 是正常侧，86 是越限侧，再回到 77 检查恢复；有延时或死区时增加时间样本并按实际设置判断。</p><p><strong>这一阶段的结果</strong>：能在“报警配置”按名称找回规则，核对输入点、阈值、级别和样本试算。不把它叫作现场已经报警。</p><h2 id="_4-页面显示与权限" tabindex="-1">4. 页面显示与权限 <a class="header-anchor" href="#_4-页面显示与权限" aria-label="Permalink to &quot;4. 页面显示与权限&quot;">​</a></h2><p>让页面使用真实点路径，不在页面里固定写一个 77。给适当的<a href="/induframe-docs/zh/guide/workspace-datapoints.html">工程角色配置调用权限</a>，再用相应工程用户检查。</p><p>开发预览需要示例值时，可按说明设置开发态默认值，但必须知道它不是设备或运行计算的新结果。</p><p><strong>这一阶段的结果</strong>：页面引用和角色权限明确，能够分清真实读取、默认值与硬编码展示。</p><h2 id="_5-持续运行与历史记录" tabindex="-1">5. 持续运行与历史记录 <a class="header-anchor" href="#_5-持续运行与历史记录" aria-label="Permalink to &quot;5. 持续运行与历史记录&quot;">​</a></h2><p>练习改成实际业务前，确认输入怎样更新、计算采用什么触发、报警怎样接收新值，再准备<a href="/induframe-docs/zh/guide/point-history.html">历史存储</a>。</p><p>按正式工程版本和<a href="/induframe-docs/zh/guide/deployments.html">更新部署流程</a>提交新内容，核对计算、报警和存储引擎及真实业务结果。“重新部署”不会替你读取最新开发代码。</p><p>不要为了验证这条练习链路，直接给真实设备写值、批量重建数据库或删掉活动报警。</p><h2 id="让-ai-完成时怎样验收" tabindex="-1">让 AI 完成时怎样验收 <a class="header-anchor" href="#让-ai-完成时怎样验收" aria-label="Permalink to &quot;让 AI 完成时怎样验收&quot;">​</a></h2><p>要求 AI 交付接入源、查询名、输入点路径、计算名及输出路径、报警名，并分开列出保存、调试和未验证项。然后按<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对页</a>逐项打开，不以一段“完成了”的回复作为验收。</p><p>后续业务值不正确时，从源查询开始一段一段查，不一次重建全部配置。</p>',29)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
